const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define Northern Hemisphere geometry
  const northernHemisphere = ee.Geometry.Rectangle([-180, 0, 180, 90]);

  // Get NO2 data for 2019 and 2020
  const no2_2019 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate('2019-01-01', '2019-12-31')
    .select('NO2_column_number_density');

  const no2_2020 = ee.ImageCollection('COPERNICUS/S5P/OFFL/L3_NO2')
    .filterDate('2020-01-01', '2020-12-31')
    .select('NO2_column_number_density');

  // Check collection sizes
  const size2019 = no2_2019.size().getInfo();
  const size2020 = no2_2020.size().getInfo();

  console.log(`2019 Images: ${size2019}`);
  console.log(`2020 Images: ${size2020}`);

  if (size2019 === 0 || size2020 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean NO2 for each year
  const mean2019 = no2_2019.mean();
  const mean2020 = no2_2020.mean();

  // Get pixel counts and mean values
  const stats2019 = mean2019.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: northernHemisphere,
    scale: 30000,
    maxPixels: 1e9
  });

  const stats2020 = mean2020.reduceRegion({
    reducer: ee.Reducer.mean().combine({
      reducer2: ee.Reducer.count(),
      sharedInputs: true
    }),
    geometry: northernHemisphere,
    scale: 30000,
    maxPixels: 1e9
  });

  const meanVal2019 = stats2019.get('NO2_column_number_density_mean').getInfo();
  const count2019 = stats2019.get('NO2_column_number_density_count').getInfo();
  const meanVal2020 = stats2020.get('NO2_column_number_density_mean').getInfo();
  const count2020 = stats2020.get('NO2_column_number_density_count').getInfo();

  console.log(`2019 Mean NO2: ${meanVal2019?.toFixed(6) || 'None'}, Pixels: ${count2019}`);
  console.log(`2020 Mean NO2: ${meanVal2020?.toFixed(6) || 'None'}, Pixels: ${count2020}`);

  // Check for valid pixels
  if (count2019 === 0 || count2020 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (meanVal2019 === null || meanVal2020 === null || 
      isNaN(meanVal2019) || isNaN(meanVal2020) ||
      meanVal2019 < 0 || meanVal2020 < 0) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare values and determine answer
  if (meanVal2020 > meanVal2019) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
